esqlQuery.esql:
TS metrics-supabase.metrics.otel-*
// postgresql_restarts_total is a counter. INCREASE() is reset-safe, so a database that
// bounced (and therefore reset its own counters) is still counted correctly.
| STATS `Restarts` = SUM(INCREASE(postgresql_restarts_total))
    BY resource.attributes.supabase_project_ref
// Any restart is worth investigating. Raise above 0 only if rolling maintenance is expected.
| WHERE `Restarts` > 0
